/**
 * Concatenate supabase/migrations/*.sql into docs/BOOTSTRAP_FRESH_DATABASE.sql
 * for one-shot execution on a new Supabase project (SQL Editor).
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, "..");
const migrationsDir = path.join(root, "supabase", "migrations");
const outFile = path.join(root, "docs", "BOOTSTRAP_FRESH_DATABASE.sql");

const header = `-- VegaPal — fresh Supabase database bootstrap
-- Generated by: node scripts/build-bootstrap-sql.mjs
-- Do not edit by hand; change files in supabase/migrations/ and regenerate.
--
-- Prerequisites (Supabase SQL Editor on a NEW project):
--   - Auth schema exists (default on Supabase)
--   - Extensions: pgcrypto (gen_random_uuid) — enabled below
--
-- After this script:
--   1. Configure Auth URLs (see docs/MIGRATION_GUIDE.md)
--   2. Set Vercel env vars to the new project
--   3. Promote first admin: UPDATE public.profiles SET role = 'admin' WHERE email = 'you@example.com';
--

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

`;

const files = fs.readdirSync(migrationsDir).filter((f) => f.endsWith(".sql")).sort();

const parts = [header];
for (const file of files) {
  const sql = fs.readFileSync(path.join(migrationsDir, file), "utf8").trim();
  parts.push(`-- ========== ${file} ==========\n\n${sql}\n\n`);
}

fs.writeFileSync(outFile, parts.join("\n"), "utf8");
console.log(`Wrote ${outFile} (${files.length} migrations)`);
